mapper.select:
select o.order_id, o.order_no, o.order_type, o.user_id, o.vehicle_id, o.merchant_id, o.contact_name, o.contact_phone, o.address_id, o.vehicle_price, o.total_amount, o.paid_amount, o.payment_method, o.insurance_info, o.expect_date, o.expect_time_slot, o.old_vehicle_id, o.old_valuation, o.new_order_id, o.status, o.cancel_reason, o.create_time, o.update_time, v.model_name as vehicle_name, ov.model_name as old_car_brand, uv.license_year as old_license_year, uv.license_month as old_license_month, uv.mileage as old_mileage from stad_unified_order o left join stad_vehicle v on o.vehicle_id = v.vehicle_id left join stad_vehicle_used uv on o.old_vehicle_id = uv.vehicle_id left join stad_vehicle ov on uv.vehicle_id = ov.vehicle_id
AND o.order_type = #{orderType}
AND o.status = #{paymentStatus}
AND (o.order_no like concat('%',#{keyword},'%') OR o.contact_name like concat('%',#{keyword},'%') OR v.model_name like concat('%',#{keyword},'%'))
order by o.create_time desc
